25	// Connected components by label propagation.
26	//
27	// Every vertex starts as its own component label (IDs[i] = i) and repeatedly
28	// takes the minimum label among itself and its in-neighbors.  A vertex is put
29	// on the next frontier whenever its label actually decreased this round, so the
30	// algorithm terminates once no label changes, i.e. every component has been
31	// flooded by the smallest vertex id it contains.
32	//
33	// prevIDs holds the snapshot of IDs taken at the start of the round.  A vertex
34	// d is only reported (returns 1) by the update that moves it away from its
35	// snapshot value, so d appears at most once in the output frontier even though
36	// several in-neighbors may lower its label in the same round.
37	#include "ligra.h"
38	
39	struct CC_F {
40	  uintE* IDs, *prevIDs;
41	  CC_F(uintE* _IDs, uintE* _prevIDs) : IDs(_IDs), prevIDs(_prevIDs) {}
42	  inline bool update(uintE s, uintE d) { //Update: write the smaller label
43	    uintE origID = IDs[d];
44	    if(IDs[s] < origID) {
45	      IDs[d] = min(origID,IDs[s]);
46	      //only output d the first time its label leaves the round's snapshot
47	      if(origID == prevIDs[d]) return 1;
48	    }
49	    return 0;
50	  }
51	  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
52	    uintE origID = IDs[d];
53	    return (writeMin(&IDs[d],IDs[s]) && origID == prevIDs[d]);
54	  }
55	  //visit every edge out of the frontier -- labels can always shrink
56	  inline bool cond (uintE d) { return cond_true(d); }
57	};
58	
59	//vertex map function to snapshot the labels at the beginning of a round
60	struct CC_Vertex_F {
61	  uintE* IDs, *prevIDs;
62	  CC_Vertex_F(uintE* _IDs, uintE* _prevIDs) : IDs(_IDs), prevIDs(_prevIDs) {}
63	  inline bool operator () (uintE i) {
64	    prevIDs[i] = IDs[i];
65	    return 1;
66	  }
67	};
68	
69	template <class vertex>
70	void Compute(graph<vertex>& GA, commandLine P) {
71	  long n = GA.n;
72	  uintE* IDs = newA(uintE,n), *prevIDs = newA(uintE,n);
73	  {parallel_for(long i=0;i<n;i++) IDs[i] = i;} //initialize unique IDs
74	
75	  bool* frontier = newA(bool,n);
76	  {parallel_for(long i=0;i<n;i++) frontier[i] = 1;}
77	  //initial frontier contains all vertices
78	  vertexSubset Frontier(n,n,frontier);
79	
80	  long rounds = 0;
81	  while(!Frontier.isEmpty()){ //iterate until IDs converge
82	    rounds++;
83	    vertexMap(Frontier,CC_Vertex_F(IDs,prevIDs));
84	    vertexSubset output = edgeMap(GA, Frontier, CC_F(IDs,prevIDs));
85	    Frontier.del();
86	    Frontier = output;
87	  }
88	  Frontier.del();
89	
90	  //count the number of distinct labels left in IDs by marking each one seen
91	  bool* seen = newA(bool,n);
92	  {parallel_for(long i=0;i<n;i++) seen[i] = 0;}
93	  for(long i=0;i<n;i++) seen[IDs[i]] = 1;
94	  long components = 0;
95	  for(long i=0;i<n;i++) if(seen[i]) components++;
96	
97	  cout << "Components rounds: " << rounds << endl;
98	  cout << "Components: " << components << endl;
99	
100	  free(seen); free(IDs); free(prevIDs);
101	}
